/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METSalesOrderCancelResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_cancelResult">Result of the cancellation</param>
    /// <param name = "_cancelMessage">Message Result</param>
    /// <returns>new contract</returns>
    public static METSalesOrderCancelResponseContract newFromParameters(METProcessingStatus _cancelResult, Description255 _cancelMessage)
    {
        METSalesOrderCancelResponseContract salesOrderCancelResponse = new METSalesOrderCancelResponseContract();

        salesOrderCancelResponse.parmCancelResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_cancelResult)));
        salesOrderCancelResponse.parmCancelMessage(_cancelMessage);

        return salesOrderCancelResponse;
    }
